#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    vector<long long> positions;
    positions.reserve(N);

    long long total = 0;
    for (int i = 0; i < N; ++i) {
        positions.push_back(total);
        long long arc;
        cin >> arc;
        total += arc;
    }

    if (total % 2 != 0) {
        cout << "N\n";
        return 0;
    }

    unordered_set<long long> trees(positions.begin(), positions.end());
    long long half = total / 2;
    int matches = 0;

    for (long long position : positions) {
        if (trees.count((position + half) % total)) {
            ++matches;
        }
    }

    cout << (matches >= 4 ? "S\n" : "N\n");
    return 0;
}
